def primes_below(n: int):
    """Yield prime numbers below n."""
    if n <= 2:
        return
    # Sieve of Eratosthenes
    sieve = [True] * n
    sieve[0] = False
    sieve[1] = False
    for i in range(2, int(n**0.5) + 1):
        if sieve[i]:
            for j in range(i * i, n, i):
                sieve[j] = False
    for i in range(2, n):
        if sieve[i]:
            yield i


# Tests
def test_primes_below():
    # Test with small n
    assert list(primes_below(10)) == [2, 3, 5, 7]
    assert list(primes_below(2)) == []
    assert list
